n = int(input())
q = list(map(int, input().split()))
a = list(map(int, input().split()))
b = list(map(int, input().split()))
ans = 0

for x in range(max(q) + 1):
    y = float('inf')
    for i in range(n):
        if q[i] < x * a[i]:
            y = -float('inf')
            break
        elif b[i] > 0:
            y = min(y, (q[i] - x * a[i]) // b[i])
    if y != -float('inf'):
        ans = max(ans, x + y)

print(ans)
